import heapq
def widest_plan(H,participants,roots):
 P=sorted(participants);idx={v:i for i,v in enumerate(P)};k=len(P)
 cap=[{} for _ in range(k)]
 for a,b,d in H.edges(data=True):
  c=d.get('capacity',0)
  if c>0:cap[idx[a]][idx[b]]=cap[idx[a]].get(idx[b],0)+c
 recs=[]
 for rv in sorted(roots):
  r=idx[rv];rem=roots[rv]
  while rem>0:
   val=[-1]*k;par=[-1]*k;val[r]=10**100;pq=[(-val[r],r)]
   while pq:
    nv,u=heapq.heappop(pq);nv=-nv
    if nv!=val[u]:continue
    for v,c in cap[u].items():
     z=min(c,nv)
     if z>val[v]:val[v]=z;par[v]=u;heapq.heappush(pq,(-z,v))
   if any(val[i]<0 for i in range(k)):return None
   w=min(rem,min(val))
   if w<=0:return None
   es=[]
   for v in range(k):
    if v==r:continue
    u=par[v]
    if u<0:return None
    es.append((u,v));cap[u][v]-=w
    if cap[u][v]==0:del cap[u][v]
   recs.append((rv,w,es));rem-=w
 return recs
